'use strict';

/**
 * Source list for scripts/generate-site-favicons.js.
 * Each blurb is a site-specific note. Measured sizes, link tags, colours
 * and icon URLs are filled in at build time from the live response.
 */

function site(slug, name, domain, category, blurb, pages, domains) {
    return {
        slug,
        name,
        domain,
        category,
        blurb,
        domains: domains || [domain],
        pages: pages || ['https://' + domain + '/', 'https://www.' + domain + '/']
    };
}

