// Entries above the KEEP set stay in source as unused alternates. Only KEEP is exported.
const FILTERED = SITES;

const CATEGORIES = new Set([
    'search', 'social', 'messaging', 'video', 'music', 'shopping', 'tech', 'ai',
    'productivity', 'design', 'developer', 'cloud', 'finance', 'news', 'sports',
    'travel', 'food', 'education', 'health', 'realestate', 'logistics', 'photo',
    'security', 'gaming', 'reference'
]);

function assertCatalog(list) {
    const slugs = new Set();
    const names = new Set();
    const blurbs = new Set();
    const starts = new Map();
    for (const entry of list) {
        if (!/^[a-z0-9-]+$/.test(entry.slug)) throw new Error('bad slug ' + entry.slug);
        if (slugs.has(entry.slug)) throw new Error('duplicate slug ' + entry.slug);
        slugs.add(entry.slug);
        if (names.has(entry.name)) throw new Error('duplicate name ' + entry.name);
        names.add(entry.name);
        if (!CATEGORIES.has(entry.category)) throw new Error('bad category ' + entry.slug + ' ' + entry.category);
        if (!entry.blurb || entry.blurb.length < 80) throw new Error('short blurb ' + entry.slug);
        if (/\{host\}|\{name\}|owns the (mark|artwork|logo)/i.test(entry.blurb)) throw new Error('template blurb ' + entry.slug);
        if (blurbs.has(entry.blurb)) throw new Error('duplicate blurb ' + entry.slug);
        blurbs.add(entry.blurb);
        const start = entry.blurb.slice(0, 28);
        starts.set(start, (starts.get(start) || 0) + 1);
        if (starts.get(start) > 2) throw new Error('repeated opening ' + start);
        if (!entry.pages.length) throw new Error('no pages ' + entry.slug);
    }
}

